<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import DOMPurify from 'dompurify';
const props=defineProps({modelValue:{type:String,default:''},disabled:Boolean});
const emit=defineEmits(['update:modelValue','plain']);
const editor=ref(null),linkOpen=ref(false),linkUrl=ref(''); let selection;
const clean=html=>DOMPurify.sanitize(html,{ALLOWED_TAGS:['p','br','div','strong','b','i','em','u','s','ul','ol','li','blockquote','a','span','h2','h3','font'],ALLOWED_ATTR:['href','color','face','size','target','rel']});
function update(){emit('update:modelValue',editor.value.innerHTML);emit('plain',editor.value.innerText);}
function command(name,value){editor.value.focus();document.execCommand(name,false,value);update();}
function openLink(){const s=getSelection();selection=s.rangeCount?s.getRangeAt(0).cloneRange():null;linkOpen.value=true;linkUrl.value='https://';}
function insertLink(){if(!/^https?:\/\/[^\s]+$/i.test(linkUrl.value)&&!/^mailto:[^\s@]+@[^\s]+$/.test(linkUrl.value))return;editor.value.focus();if(selection){const s=getSelection();s.removeAllRanges();s.addRange(selection);}document.execCommand('createLink',false,linkUrl.value);linkOpen.value=false;update();}
function paste(e){e.preventDefault();const html=e.clipboardData.getData('text/html'),plain=e.clipboardData.getData('text/plain');document.execCommand(html?'insertHTML':'insertText',false,html?clean(html):plain);update();}
watch(()=>props.modelValue,v=>{if(editor.value&&v!==editor.value.innerHTML)editor.value.innerHTML=clean(v);});
onMounted(()=>{editor.value.innerHTML=clean(props.modelValue);});
onBeforeUnmount(()=>{selection=null;});
</script>
<template><div class="rich-compose"><div class="format-toolbar" role="toolbar" aria-label="文字格式"><button type="button" title="撤销" aria-label="撤销" @mousedown.prevent @click="command('undo')">↶</button><button type="button" title="重做" aria-label="重做" @mousedown.prevent @click="command('redo')">↷</button><span></span><button type="button" title="加粗 (Ctrl+B)" aria-label="加粗" @mousedown.prevent @click="command('bold')"><b>B</b></button><button type="button" title="斜体 (Ctrl+I)" aria-label="斜体" @mousedown.prevent @click="command('italic')"><i>I</i></button><button type="button" title="下划线 (Ctrl+U)" aria-label="下划线" @mousedown.prevent @click="command('underline')"><u>U</u></button><button type="button" title="项目符号" aria-label="项目符号" @mousedown.prevent @click="command('insertUnorderedList')">☷</button><button type="button" title="编号列表" aria-label="编号列表" @mousedown.prevent @click="command('insertOrderedList')">1.</button><button type="button" title="引用" aria-label="引用" @mousedown.prevent @click="command('formatBlock','blockquote')">❞</button><button type="button" title="插入链接" aria-label="插入链接" @mousedown.prevent @click="openLink">↗</button><button type="button" title="清除格式" aria-label="清除格式" @mousedown.prevent @click="command('removeFormat')">Tx</button></div><div v-if="linkOpen" class="link-entry"><input v-model="linkUrl" aria-label="链接地址" placeholder="https://" @keydown.enter.prevent="insertLink"/><button type="button" @click="insertLink">插入</button><button type="button" @click="linkOpen=false">取消</button></div><div ref="editor" class="compose-editor" :contenteditable="!disabled" role="textbox" aria-label="邮件正文" aria-multiline="true" data-placeholder="写下你想说的话…" @input="update" @paste="paste" @drop.prevent></div></div></template>
<style scoped>.format-toolbar{display:flex;gap:3px;flex-wrap:wrap;padding:8px 14px;border-bottom:1px solid var(--mail-border,#e6e8ec);background:var(--mail-bg,#f8fafd)}.format-toolbar button{border:0;background:transparent;color:inherit;width:30px;height:30px;border-radius:4px;cursor:pointer}.format-toolbar button:hover{background:#d3e3fd;color:#174ea6}.format-toolbar span{border-left:1px solid #dadce0;margin:4px}.compose-editor{min-height:200px;max-height:45vh;overflow:auto;padding:18px 22px;outline:none;font:15px/1.65 Arial,sans-serif;overflow-wrap:anywhere}.compose-editor:empty:before{content:attr(data-placeholder);color:#777;pointer-events:none}.compose-editor :deep(blockquote){border-left:3px solid #dadce0;padding-left:12px;color:#5f6368}.link-entry{display:flex;gap:8px;padding:8px 20px}.link-entry input{flex:1;min-width:0}</style>
